mapper.select:
SELECT id, tenant_id, user_id, session_id, target_type, target_id, binding_id,
       selection_order, create_time, update_time
FROM chat_session_rag_binding_selection
WHERE user_id = #{userId} AND session_id = #{sessionId}
AND (tenant_id IS NULL OR tenant_id = '')AND tenant_id = #{tenantId}
ORDER BY selection_order ASC, id ASC

